#pragma once

#include <cstdint>

// Aircraft icons as alpha masks (white shape, nose up), raw-deflate
// compressed. Icons by ADS-B Radar for macOS - https://adsb-radar.com -
// https://apps.apple.com/app/id1538149835. Generated by
// scripts/gen_aircraft_icons.js from assets/aircraft_icons.
namespace data {

struct IconMask {
  const char* name;      // the SVG's file name, e.g. "a320"
  uint16_t size;         // edge, px (square)
  const uint8_t* data;   // raw deflate of size*size alpha bytes
  uint32_t len;
};

extern const IconMask kIconMasks[];
extern const int kIconMaskCount;

}  // namespace data
